<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> monthly_sales (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">month</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
